41	 * @param {ProviderModel[]} models An array of available models with their costs.
42	 * @returns {number | undefined} The calculated cost, or undefined if it can't be calculated.
43	 */
44	export function calculateCost(
45	  modelName: string,
46	  config: ProviderConfig,
47	  promptTokens: number | undefined,
48	  completionTokens: number | undefined,
49	  models: ProviderModel[],
50	): number | undefined {
51	  if (
52	    !Number.isFinite(promptTokens) ||
53	    !Number.isFinite(completionTokens) ||
54	    typeof promptTokens === 'undefined' ||
55	    typeof completionTokens === 'undefined'
56	  ) {
57	    return undefined;
58	  }
59	
60	  const model = models.find((m) => m.id === modelName);
61	  if (!model || !model.cost) {
62	    return undefined;
63	  }
64	
65	  const inputCost = config.cost ?? model.cost.input;
66	  const outputCost = config.cost ?? model.cost.output;
67	  return inputCost * promptTokens + outputCost * completionTokens;
68	}
