70	/**
71	 * Checks if a string looks like it's attempting to be JSON.
72	 * This helps distinguish between actual JSON attempts and plain text that happens to start/end with brackets.
73	 */
74	function looksLikeJson(prompt: string): boolean {
75	  const trimmed = prompt.trim();
76	
77	  // Objects starting with { are almost always JSON
78	  if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
79	    return true;
80	  }
81	
82	  // Arrays starting with [ need more careful checking
83	  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
84	    // Check if the character after [ suggests it's JSON
85	    // Valid JSON array starts: ", {, [, whitespace, number, or true/false/null
86	    const afterBracket = trimmed.slice(1).trimStart();
87	    if (
88	      afterBracket.startsWith('"') ||
89	      afterBracket.startsWith('{') ||
90	      afterBracket.startsWith('[') ||
91	      /^[\d-]/.test(afterBracket) || // number
92	      /^(true|false|null)/.test(afterBracket) // boolean or null
93	    ) {
94	      return true;
95	    }
96	    // If it's just whitespace or empty, it might be JSON
97	    if (afterBracket.length === 0 || /^\s+$/.test(afterBracket)) {
98	      return true;
99	    }
100	    // Otherwise, it's likely plain text (e.g., [INST]...[/INST])
101	    return false;
102	  }
103	
104	  return false;
105	}
